## builtin_interfaces/Time -> seconds. Returns 0.0 for the "use latest" stamp.
static func stamp_to_sec(stamp) -> float:
	if stamp == null:
		return 0.0
	return float(stamp.sec) + float(stamp.nanosec) * 1e-9


static func sec_to_stamp(sec: float):
	var msg = RosMsg.from_type("builtin_interfaces/msg/Time")
	msg.sec = int(floor(sec))
	msg.nanosec = int(round((sec - floor(sec)) * 1e9))
	return msg


