func _subscribe() -> void:
	_sub = null
	_queue.clear()
	_messages_received = 0
	if context == null or context.ros_node == null:
		return
	var topic := String(topic_prop.value).strip_edges()
	if topic.is_empty():
		_update_topic_status()
		_viz_reset()
		return
	var type := _viz_active_message_type()
	if type.is_empty():
		set_status(VizStatus.Level.ERROR, "Topic", "No message type resolved for this topic.")
		return
	_sub = context.ros_node.create_subscription(topic, type, _on_ros_message, build_qos())
	_viz_reset()
	_update_topic_status()


## rclgd already hops to the main thread, so this only buffers; the real work
## happens in [method viz_update] so a 1 kHz topic cannot outrun the renderer.
func _on_ros_message(msg: RosMsg) -> void:
	_messages_received += 1
	if latest_only:
		_queue.clear()
	_queue.append(msg)
	if _queue.size() > MAX_QUEUE:
		_queue = _queue.slice(_queue.size() - MAX_QUEUE)


func viz_update(delta: float) -> void:
	if not enabled:
		# Keep the queue from growing while the display is switched off.
		_queue.clear()
		return
	if not _queue.is_empty():
		var batch := _queue
		_queue = []
		for msg in batch:
			_viz_message(msg)
		_update_topic_status()
	super.viz_update(delta)


func _viz_enabled_changed(on: bool) -> void:
	# Unsubscribe while disabled so a switched-off display costs no bandwidth,
	# matching what RViz does.
	if on:
		_subscribe()
	else:
		_sub = null
		_queue.clear()


func _update_topic_status() -> void:
	var topic := String(topic_prop.value).strip_edges()
	if topic.is_empty():
		set_status(VizStatus.Level.WARN, "Topic", "No topic set.")
		return
	if _messages_received == 0:
		var n := context.ros_node.count_publishers(topic) if context != null else 0
		if n == 0:
			set_status(VizStatus.Level.WARN, "Topic",
				"No messages received; nothing is publishing on %s." % topic)
		else:
			set_status(VizStatus.Level.WARN, "Topic",
				"No messages received from %d publisher(s) on %s — check the QoS settings." % [n, topic])
		return
	set_status(VizStatus.Level.OK, "Topic", "%d messages received." % _messages_received)


func _viz_teardown() -> void:
	_sub = null
	_queue.clear()


func frame_latest_time(frame: String) -> float:
	return _tf.get_frame_latest_time(frame) if _tf != null else 0.0


## parent -> [children]. Frames with no parent are listed under "".
func frame_tree() -> Dictionary:
	var tree := {"": []}
	for f in _frame_names:
		var p := frame_parent(f)
		if not tree.has(p):
			tree[p] = []
		tree[p].append(f)
	# A parent that is itself only ever a parent never shows up in
	# get_frame_names(); make sure it still roots its subtree.
