func _viz_message(msg: RosMsg) -> void:
	_width = int(msg.info.width)
	_height = int(msg.info.height)
	_resolution = float(msg.info.resolution)
	if _width <= 0 or _height <= 0:
		set_status(VizStatus.Level.WARN, "Map", "Grid has zero size.")
		return
	_cells = msg.data
	_origin = VizConvert.pose(msg.info.origin)
	_frame = VizConvert.frame_of(msg)
	_stamp = VizConvert.stamp_of(msg)

	_resolution_prop.value = _resolution
	_size_prop.value = "%d x %d cells (%.2f x %.2f m)" % [
		_width, _height, _width * _resolution, _height * _resolution]
	var o := rclgd.godot_to_ros_vector(_origin.origin)
	_origin_prop.value = "%.3f; %.3f; %.3f" % [o.x, o.y, o.z]

	_upload()
	set_status(VizStatus.Level.OK, "Map", "%d x %d at %.3f m/cell" % [_width, _height, _resolution])


func _on_update(msg: RosMsg) -> void:
	if _cells.is_empty():
		return
	var x := int(msg.x)
	var y := int(msg.y)
	var w := int(msg.width)
	var h := int(msg.height)
	var patch: PackedInt32Array = msg.data
	if w <= 0 or h <= 0 or patch.size() < w * h:
		return
	if x < 0 or y < 0 or x + w > _width or y + h > _height:
		set_status(VizStatus.Level.WARN, "Map",
			"Update rectangle falls outside the grid; ignored.")
		return
	for row in h:
		var dst := (y + row) * _width + x
		var src := row * w
		for col in w:
			_cells[dst + col] = patch[src + col]
	_upload()


func _upload() -> void:
	if _cells.size() < _width * _height:
		set_status(VizStatus.Level.ERROR, "Map",
			"Grid data is short: %d cells for %d x %d." % [_cells.size(), _width, _height])
		return
	var bytes := _cells.to_byte_array()
	var needed := _width * _height * 4
	if bytes.size() != needed:
		bytes.resize(needed)
	var img := Image.create_from_data(_width, _height, false, Image.FORMAT_RF, bytes)
	if _texture != null and _tex_size == Vector2i(_width, _height):
		_texture.update(img)
	else:
		_texture = ImageTexture.create_from_image(img)
		_tex_size = Vector2i(_width, _height)
	_material.set_shader_parameter("cells", _texture)
	_material.set_shader_parameter("grid_width", _width)
	_material.set_shader_parameter("grid_height", _height)


func _viz_update(_delta: float) -> void:
	if _width <= 0:
		_mesh.visible = false
		return
	var xform = context.frames.get_transform(_frame, _stamp)
	if xform == null:
		set_status(VizStatus.Level.ERROR, "Transform",
			"No transform from [%s] to [%s]: %s" % [_frame, context.frames.fixed_frame,
				context.frames.last_error])
		_mesh.visible = false
		return
	clear_status("Transform")
	_mesh.visible = true
	_mesh.transform = (xform as Transform3D) * _origin
	_mesh.scale = Vector3(_height * _resolution, 1.0, _width * _resolution)


func _viz_reset() -> void:
	_cells = PackedInt32Array()
	_width = 0

